    mut srcSize: c_int,
    mut outputSize: c_int,
    mut partialDecoding: earlyEnd_directive,
    mut dict: dict_directive,
    lowPrefix: *const BYTE,
    dictStart: *const BYTE,
    dictSize: size_t,
