        return -1;
    }

    let src0 = src as *const BYTE;
    let dst0 = dst as *mut BYTE;
    let mut ip = src0;
    let iend = ip.offset(srcSize as isize);
    let mut op = dst0;
    let oend = op.offset(outputSize as isize);

    if outputSize == 0 {
        if partialDecoding as u64 != 0 {
            return 0;
        }
        return if srcSize == 1 && *ip as c_int == 0 { 0 } else { -1 };
    }
    if srcSize == 0 {
        return -1;
    }

    let dictEnd = if dictStart.is_null() {
        ::core::ptr::null::<BYTE>()
    } else {
        dictStart.offset(dictSize as isize)
    };
    let checkOffset =
        (dictSize < (64 as c_int * ((1 as c_int) << 10 as c_int)) as size_t) as c_int;
    let shortiend = iend.offset(-16);
    let shortoend = oend.offset(-32);
    let prefix64k = dict as c_uint == withPrefix64k as c_int as c_uint;
    let using_ext_dict = dict as c_uint == usingExtDict as c_int as c_uint;
    let partial = partialDecoding as u64 != 0;

    let mut token: c_uint;
    let mut length: size_t;
    let mut offset: size_t;
    let mut match_0: *const BYTE;
    let mut cpy: *mut BYTE;

    macro_rules! fail {
        () => {
            return -((ip as *const c_char).offset_from(src) as c_long) as c_int - 1;
        };
    }

