                length = length.wrapping_add(addl);
                if (op as uptrval).wrapping_add(length as uptrval) < op as uptrval {
                    fail!();
                }
                if (ip as uptrval).wrapping_add(length as uptrval) < ip as uptrval {
                    fail!();
                }
