                LZ4_wildCopy8(op as *mut c_void, ip as *const c_void, cpy as *mut c_void);
                ip = ip.offset(length as isize);
                op = cpy;
            }

            offset = LZ4_readLE16(ip as *const c_void) as size_t;
            ip = ip.offset(2);
            match_0 = op.offset(-(offset as isize));

