            ::libc::memcpy(
                op as *mut c_void,
                ip as *const c_void,
                16 as ::libc::size_t,
            );
            op = op.offset(length as isize);
            ip = ip.offset(length as isize);

            offset = LZ4_readLE16(ip as *const c_void) as size_t;
            ip = ip.offset(2);
