                    op.offset(8) as *mut c_void,
                    match_0.offset(8) as *const c_void,
                    8 as ::libc::size_t,
                );
                ::libc::memcpy(
                    op.offset(16) as *mut c_void,
                    match_0.offset(16) as *const c_void,
                    2 as ::libc::size_t,
                );
                op = op.offset(length.wrapping_add(MINMATCH as size_t) as isize);
                continue;
            }

            read_match_length!();
        }

