                if !partial {
                    fail!();
                }
                length = if length < oend.offset_from(op) as c_long as size_t {
                    length
                } else {
                    oend.offset_from(op) as c_long as size_t
                };
            }

            let prefix_gap = lowPrefix.offset_from(match_0) as c_long as size_t;
            if length <= prefix_gap {
                ::libc::memmove(
                    op as *mut c_void,
                    dictEnd.offset(-(prefix_gap as isize)) as *const c_void,
                    length as ::libc::size_t,
                );
                op = op.offset(length as isize);
            } else {
                let copySize = prefix_gap;
                let restSize = length.wrapping_sub(copySize);
                ::libc::memcpy(
                    op as *mut c_void,
                    dictEnd.offset(-(copySize as isize)) as *const c_void,
                    copySize as ::libc::size_t,
