                    let endOfMatch = op.offset(restSize as isize);
                    let mut copyFrom = lowPrefix;
                    while op < endOfMatch {
                        *op = *copyFrom;
                        op = op.offset(1);
                        copyFrom = copyFrom.offset(1);
                    }
                } else {
                    ::libc::memcpy(
                        op as *mut c_void,
                        lowPrefix as *const c_void,
                        restSize as ::libc::size_t,
                    );
                    op = op.offset(restSize as isize);
                }
            }
            continue;
        }

        cpy = op.offset(length as isize);

        if partial && cpy > oend.offset(-(MATCH_SAFEGUARD_DISTANCE as isize)) {
            let mlen = if length < oend.offset_from(op) as c_long as size_t {
                length
            } else {
                oend.offset_from(op) as c_long as size_t
            };
            let matchEnd = match_0.offset(mlen as isize);
            let copyEnd = op.offset(mlen as isize);

            if matchEnd > op as *const BYTE {
                while op < copyEnd {
                    *op = *match_0;
                    op = op.offset(1);
                    match_0 = match_0.offset(1);
                }
            } else {
                ::libc::memcpy(
                    op as *mut c_void,
                    match_0 as *const c_void,
                    mlen as ::libc::size_t,
                );
                op = copyEnd;
            }

            if op == oend {
                return (op as *mut c_char).offset_from(dst) as c_long as c_int;
            }
            continue;
        }

        if offset < 8 {
            LZ4_write32(op as *mut c_void, 0 as U32);
            *op.offset(0) = *match_0.offset(0);
            *op.offset(1) = *match_0.offset(1);
            *op.offset(2) = *match_0.offset(2);
            *op.offset(3) = *match_0.offset(3);
            match_0 = match_0.offset(inc32table[offset as usize] as isize);
            ::libc::memcpy(
                op.offset(4) as *mut c_void,
                match_0 as *const c_void,
